// The expression parser against the reference CLI. The table (tests/parity/expressions/Expressions.tsv)
// is generated by scripts/generate-expression-parity-table.sh: for each expression, whether
// `cedar check-parse --expression` accepts it and, when it does, Rust's canonical printing of it.
// Each accepted expression must parse and print exactly that text; each rejected one must fail.

#include <cedar/Expression.hpp>
#include <cedar/Syntax.hpp>

#include <gtest/gtest.h>

#include <cstddef>
#include <fstream>
#include <string>
#include <string_view>
#include <vector>

namespace
{

struct TableRow
{
    std::size_t line{};
    bool accepted{};
    std::string expression;
    std::string canonical;
};

auto ReadTable(const std::string& path) -> std::vector<TableRow>
{
    std::ifstream input{path};
    std::vector<TableRow> rows;
    std::string line;
    std::size_t number = 0;
    while (std::getline(input, line))
    {
        ++number;
        const std::size_t first = line.find('\t');
        const std::size_t second = first == std::string::npos ? std::string::npos : line.find('\t', first + 1);
        if (second == std::string::npos)
        {
            ADD_FAILURE() << path << ":" << number << ": not three tab-separated columns";
            continue;
        }
        rows.push_back({number, line.substr(0, first) == "accept", line.substr(first + 1, second - first - 1),
                        line.substr(second + 1)});
    }
    return rows;
}

TEST(ExpressionParser, AgreesWithTheReferenceTable)
{
    const std::vector<TableRow> rows = ReadTable(CEDAR_EXPRESSION_PARITY_TABLE);
    ASSERT_GT(rows.size(), 100U);
    for (const TableRow& row : rows)
    {
        SCOPED_TRACE(testing::Message() << "table line " << row.line << ": " << row.expression);
        const auto parsed = cedar::ParseExpression(row.expression);
        if (!row.accepted)
        {
            EXPECT_FALSE(parsed.has_value()) << "accepted: " << cedar::ToCedar(*parsed);
            continue;
        }
        if (!parsed)
        {
            ADD_FAILURE() << "rejected:\n" << parsed.error().Render();
            continue;
        }
        if (!row.canonical.empty()) { EXPECT_EQ(cedar::ToCedar(*parsed), row.canonical); }
    }
}

// The tree shapes Rust builds, which the canonical text alone does not show.
TEST(ExpressionParser, BuildsRustShapes)
{
    const auto dump = [](const std::string_view text) {
        const auto parsed = cedar::ParseExpression(text);
        if (!parsed) { return "error: " + parsed.error().Render(); }
        return cedar::DumpExpression(parsed->Arena(), parsed->Root());
    };
    EXPECT_EQ(dump("1 != 2"), "(! (== 1 2))");
    EXPECT_EQ(dump("1 > 2"), "(! (<= 1 2))");
    EXPECT_EQ(dump("1 >= 2"), "(! (< 1 2))");
    EXPECT_EQ(dump("-1"), "-1");
    EXPECT_EQ(dump("-(-1)"), "(neg -1)");
    EXPECT_EQ(dump("--9223372036854775808"), "(neg -9223372036854775808)");
    EXPECT_EQ(dump("1 - 2 - 3"), "(- (- 1 2) 3)");
    EXPECT_EQ(dump("context.a && context.b && context.c"),
              "(&& (&& (. context \"a\") (. context \"b\")) (. context \"c\"))");
    // Rust's builder folds `&&` and `||` of two bool literals.
    EXPECT_EQ(dump("true && false || true"), "true");
    EXPECT_EQ(dump("true && context.a"), "(&& true (. context \"a\"))");
    EXPECT_EQ(dump("principal has a.b.c"), "(has principal \"a\" \"b\" \"c\")");
    EXPECT_EQ(dump("principal is User in Group::\"g\""), "(&& (is principal User) (in principal Group::\"g\"))");
    EXPECT_EQ(dump("decimal(context.d).lessThan(context.e)"),
              "(call lessThan (call decimal (. context \"d\")) (. context \"e\"))");
    EXPECT_EQ(dump("[1, context.a].contains(1)"), "(contains (set 1 (. context \"a\")) 1)");
}

// Constructor calls on string literals and sets of constants are folded; the written subtree is
// kept for printing. Calls that would fail at evaluation are not folded.
TEST(ExpressionParser, FoldsConstants)
{
    const auto dump = [](const std::string_view text) {
        const auto parsed = cedar::ParseExpression(text);
        if (!parsed) { return "error: " + parsed.error().Render(); }
        return cedar::DumpExpression(parsed->Arena(), parsed->Root());
    };
    EXPECT_EQ(dump("ip(\"10.0.0.1\").isInRange(ip(\"10.0.0.0/8\"))"),
              "(call isInRange (folded ip(\"10.0.0.1/32\") (call ip \"10.0.0.1\")) "
              "(folded ip(\"10.0.0.0/8\") (call ip \"10.0.0.0/8\")))");
    EXPECT_EQ(dump("decimal(\"1.5\")"), "(folded decimal(\"1.5000\") (call decimal \"1.5\"))");
    EXPECT_EQ(dump("duration(\"1h\")"), "(folded duration(\"3600000ms\") (call duration \"1h\"))");
    EXPECT_EQ(dump("datetime(\"1970-01-02\")"),
              "(folded datetime(\"1970-01-01\").offset(duration(\"86400000ms\")) (call datetime \"1970-01-02\"))");
    // Not folded: the text does not parse, the argument is not a string literal, the argument
    // count is wrong, or the function is a method.
    EXPECT_EQ(dump("ip(\"10.0.0.256\")"), "(call ip \"10.0.0.256\")");
    EXPECT_EQ(dump("decimal(1)"), "(call decimal 1)");
    EXPECT_EQ(dump("ip(\"10.0.0.1\", \"x\")"), "(call ip \"10.0.0.1\" \"x\")");
    EXPECT_EQ(dump("ip()"), "(call ip)");
    EXPECT_EQ(dump("ip(\"1.1.1.1\").isIpv4()"), "(call isIpv4 (folded ip(\"1.1.1.1/32\") (call ip \"1.1.1.1\")))");
    // Sets: sorted and deduplicated in the value, as written in `written`; nested constants fold.
    EXPECT_EQ(dump("[2, 1, 2].contains(1)"), "(contains (folded [1, 2] (set 2 1 2)) 1)");
    EXPECT_EQ(dump("[].isEmpty()"), "(isEmpty (folded [] (set)))");
    EXPECT_EQ(dump("[[1], ip(\"::1\")]"),
              "(folded [[1], ip(\"::1/128\")] (set (folded [1] (set 1)) (folded ip(\"::1/128\") (call ip \"::1\"))))");
    EXPECT_EQ(dump("[ip(\"x\")]"), "(set (call ip \"x\"))");
    EXPECT_EQ(dump("[{a: 1}]"), "(set (record (\"a\" 1)))");

    // Printing reads what was written.
    const auto parsed = cedar::ParseExpression("[ip(\"10.0.0.1\"), decimal(\"1.5\"), 2, 2]");
    ASSERT_TRUE(parsed.has_value());
    EXPECT_EQ(cedar::ToCedar(*parsed), "[ip(\"10.0.0.1\"), decimal(\"1.5\"), 2, 2]");
}

TEST(ExpressionParser, KeepsSpans)
{
    const auto parsed = cedar::ParseExpression("  principal.name == \"x\"");
    ASSERT_TRUE(parsed.has_value());
    const cedar::ExpressionArena& arena = parsed->Arena();
    for (std::size_t index = 0; index < arena.Size(); ++index)
    {
        EXPECT_TRUE(arena.Span(static_cast<cedar::ExpressionIndex>(index)).has_value()) << "node " << index;
    }
    EXPECT_EQ(arena.Span(parsed->Root()), (cedar::SourceSpan{2, 23}));
}

TEST(ExpressionParser, ReportsTheFirstSyntaxErrorOnly)
{
    // `foo` is a conversion error, `)` a syntax error: Rust reports only the syntax error.
    const auto parsed = cedar::ParseExpression("foo(1) + )");
    ASSERT_FALSE(parsed.has_value());
    ASSERT_EQ(parsed.error().Diagnostics().size(), 1U);
    EXPECT_EQ(parsed.error().Primary().code, cedar::DiagnosticCode::UnexpectedToken);
    EXPECT_EQ(parsed.error().Primary().primary, (cedar::SourceSpan{9, 10}));
}

TEST(ExpressionParser, ReportsEveryConversionError)
{
    const auto parsed = cedar::ParseExpression("[foo(1), principal.if, {a: 1, a: 2}]");
    ASSERT_FALSE(parsed.has_value());
    EXPECT_TRUE(parsed.error().HasCode(cedar::DiagnosticCode::UnknownFunction));
    EXPECT_TRUE(parsed.error().HasCode(cedar::DiagnosticCode::ReservedIdentifier));
    EXPECT_TRUE(parsed.error().HasCode(cedar::DiagnosticCode::DuplicateRecordKey));
}

TEST(ExpressionParser, LimitsNesting)
{
    const auto nested = [](const std::size_t depth) {
        return std::string(depth, '(') + "1" + std::string(depth, ')');
    };
    // The outermost expression is one level, so 999 parentheses are 1000 levels.
    EXPECT_TRUE(cedar::ParseExpression(nested(999)).has_value());
    const auto tooDeep = cedar::ParseExpression(nested(1000));
    ASSERT_FALSE(tooDeep.has_value());
    EXPECT_TRUE(tooDeep.error().HasCode(cedar::DiagnosticCode::NestingTooDeep));
    EXPECT_FALSE(cedar::ParseExpression(nested(100000)).has_value());
    EXPECT_FALSE(cedar::ParseExpression(std::string(100000, '[')).has_value());
}

TEST(ExpressionParser, ReadsEntityUids)
{
    const auto uid = cedar::ParseEntityUid(" Photos::User :: // comment\n \"al\\\"ice\" ");
    ASSERT_TRUE(uid.has_value()) << uid.error().Render();
    EXPECT_EQ(uid->ToString(), "Photos::User::\"al\\\"ice\"");
    EXPECT_TRUE(cedar::ParseEntityUid("principal::\"x\"").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("User").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("User::\"a\" + 1").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("User::{a: \"b\"}").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("if::\"x\"").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("__cedar::\"x\"").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("User::\"\\q\"").has_value());
    EXPECT_FALSE(cedar::ParseEntityUid("").has_value());
}

} // namespace
